package com.daodian.clock;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.webkit.*;
import org.json.*;
import java.io.*;
import java.time.LocalDate;

public final class MainActivity extends Activity {
    private WebView web;
    private final BroadcastReceiver updates=new BroadcastReceiver(){public void onReceive(Context c,Intent i){refresh();}};
    protected void onCreate(Bundle state){super.onCreate(state);Notifications.init(this);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);web.setBackgroundColor(Color.WHITE);web.addJavascriptInterface(new Bridge(),"AndroidBridge");web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri u=request.getUrl();try{if(!"appassets.androidplatform.net".equals(u.getHost()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));String path=u.getPath();if(path==null||path.contains(".."))throw new IOException();if(path.startsWith("/screenshots/")){String name=path.substring(13);if(!name.matches("[A-Za-z0-9_.-]+"))throw new IOException();return new WebResourceResponse("image/png",null,new FileInputStream(new File(new File(getFilesDir(),"screenshots"),name)));}String asset=path.substring(1);String mime=asset.endsWith(".js")?"application/javascript":asset.endsWith(".css")?"text/css":asset.endsWith(".ttf")?"font/ttf":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open(asset));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return !"appassets.androidplatform.net".equals(request.getUrl().getHost());}});setContentView(web);if(TaskService.instance==null)Records.get(this).recoverInterrupted();androidx.core.content.ContextCompat.registerReceiver(this,updates,new IntentFilter("com.daodian.clock.STATE_CHANGED"),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);web.loadUrl("https://appassets.androidplatform.net/ui/index.html");Scheduler.reschedule(this);Records.get(this).cleanupScreenshots(this,new Prefs(this).retention());}
    protected void onResume(){super.onResume();if(web!=null){Scheduler.reschedule(this);refresh();}}
    private void refresh(){runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.App&&window.App.refresh()",null);});}
    public void onBackPressed(){web.evaluateJavascript("window.App?window.App.back():false",value->{if("false".equals(value))MainActivity.super.onBackPressed();});}
    protected void onDestroy(){unregisterReceiver(updates);web.removeJavascriptInterface("AndroidBridge");web.destroy();web=null;super.onDestroy();}
    private void setting(String id){try{Intent i;if(id.equals("access"))i=new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS);else if(id.equals("alarm"))i=Build.VERSION.SDK_INT>=31?new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())):new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()));else if(id.equals("battery"))i=new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS);else if(id.equals("notification")){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},40);return;}i=new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());}else i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Exception ignored){startActivity(new Intent(Settings.ACTION_SETTINGS));}}
    public final class Bridge {
        @JavascriptInterface public String state(){return AppState.read(MainActivity.this).toString();}
        @JavascriptInterface public String invoke(String action,String payload){JSONObject out=new JSONObject();try{JSONObject data=new JSONObject(payload==null?"{}":payload);Prefs p=new Prefs(MainActivity.this);switch(action){case"onboard":p.storage.edit().putBoolean("onboard_done",data.optBoolean("done",true)).commit();break;case"savePlan":p.savePlan(data.getString("kind"),data.getJSONObject("plan"));Scheduler.reschedule(MainActivity.this);break;case"master":p.master(data.getBoolean("enabled"));Scheduler.reschedule(MainActivity.this);if(!p.master()&&TaskService.instance!=null&&TaskService.instance.activeRecord()!=null&&TaskService.instance.activeRecord().optString("trigger").equals("定时"))TaskService.cancel(MainActivity.this);break;case"settings":runOnUiThread(()->setting(data.optString("id")));break;case"bootConfirmed":p.bootConfirmed(data.getBoolean("value"));break;case"executionMode":p.executionMode(data.getString("mode"));Scheduler.reschedule(MainActivity.this);break;case"flexibleRule":p.flexibleRule(data.getBoolean("enabled"));break;case"start":if(TaskService.instance!=null){out.put("ok",false).put("error","当前执行或邮件发送尚未结束，请稍后再试");return out.toString();}String kind=data.getString("kind");if(!kind.equals("clockin")&&!kind.equals("clockout"))throw new IllegalArgumentException();TaskService.start(MainActivity.this,kind,"手动",System.currentTimeMillis(),LocalDate.now(com.daodian.clock.core.ScheduleRules.ZONE).toString(),data.optString("mode","TEST"));break;case"stop":TaskService.cancel(MainActivity.this);break;case"mail":p.saveMail(data.getString("address"),data.getBoolean("enabled"),data.optString("authorization",""));break;case"mailTest":MailJobs.connection(MainActivity.this);break;case"mailResend":MailJobs.resend(MainActivity.this,data.getString("id"));break;case"retention":int days=data.getInt("days");if(days!=7&&days!=30&&days!=90)throw new IllegalArgumentException();p.retention(days);Records.get(MainActivity.this).cleanupScreenshots(MainActivity.this,days);break;case"reminders":p.reminders(data.getBoolean("enabled"));Scheduler.reschedule(MainActivity.this);break;case"theme":String t=data.getString("theme");if(!t.equals("system")&&!t.equals("light")&&!t.equals("dark"))throw new IllegalArgumentException();p.theme(t);break;default:throw new IllegalArgumentException();}out.put("ok",true);}catch(Exception e){try{out.put("ok",false).put("error","操作未完成，请检查输入、权限或邮箱配置");}catch(Exception ignored){}}refresh();return out.toString();}
    }
}
